"""Shared Alembic autogenerate helpers."""

from __future__ import annotations

from typing import Any

from alembic.autogenerate import rewriter
from alembic.operations import ops


def build_safe_autogenerate_rewriter() -> rewriter.Rewriter:
    """Mark supported autogenerated DDL operations as idempotent."""
    writer = rewriter.Rewriter()

    @writer.rewrites(ops.AddColumnOp)
    @writer.rewrites(ops.CreateIndexOp)
    def add_if_not_exists(_context: Any, _revision: Any, op: Any) -> Any:
        op.if_not_exists = True
        return op

    @writer.rewrites(ops.DropConstraintOp)
    @writer.rewrites(ops.DropIndexOp)
    def add_if_exists(_context: Any, _revision: Any, op: Any) -> Any:
        op.if_exists = True
        return op

    return writer


safe_autogenerate_rewriter = build_safe_autogenerate_rewriter()
